{
  "appearance_facts": [
    {
      "location": "Store B monthly sales dashboard",
      "fact": "The chart is a vertical bar chart titled “Monthly Sales for Store B in City Y” with three blue bars labeled April, May, and June along the Month axis."
    },
    {
      "location": "April bar",
      "fact": "The April bar reaches the 300 gridline on the Sales axis, making it visibly taller than the June bar and shorter than the May bar."
    },
    {
      "location": "May bar",
      "fact": "The May bar is the tallest bar, reaching approximately 385 on the Sales axis, well above the dashed Average line."
    },
    {
      "location": "June bar",
      "fact": "The June bar reaches the 200 gridline, aligning with the dashed Average line; it is the shortest of the three bars."
    },
    {
      "location": "Average reference line",
      "fact": "A horizontal dashed black line labeled “Average” runs across the chart at the 200 Sales level."
    },
    {
      "location": "Y-axis scale",
      "fact": "The Sales axis is marked from 0 to 400 in increments of 50, with the top visible tick at 400."
    },
    {
      "location": "Bar colors",
      "fact": "All three monthly bars are filled with the same medium blue color."
    },
    {
      "location": "X-axis labels",
      "fact": "The Month axis labels appear in left-to-right order as April, May, and June."
    }
  ],
  "printed_facts": [
    {
      "location": "Chart title",
      "fact": "“Monthly Sales for Store B in City Y”"
    },
    {
      "location": "Y-axis label and ticks",
      "fact": "“Sales” with printed ticks at 0, 50, 100, 150, 200, 250, 300, 350, and 400."
    },
    {
      "location": "X-axis label and ticks",
      "fact": "“Month” with printed category labels “April,” “May,” and “June.”"
    },
    {
      "location": "Reference line annotation",
      "fact": "The dashed horizontal line is annotated “Average” and sits at the 200 Sales level."
    },
    {
      "location": "Form primary field",
      "fact": "The form’s primary field is labeled “June sales route” with options “Route June to low-sales response,” “Keep June on normal sales monitoring,” and “Route June to strong-sales response.”"
    },
    {
      "location": "Form companion fields",
      "fact": "Required selects include “Store unit” (Store B), “Review month” (June), “Sales record” (Monthly sales), and “Operations program” (Monthly sales status routing)."
    },
    {
      "location": "Page instructions",
      "fact": "Instructions state to review the Store B monthly sales dashboard for April through June and use it as the evidence source for the June sales route."
    },
    {
      "location": "Completion control",
      "fact": "The form’s completion button is labeled “Submit Form.”"
    }
  ],
  "public_definitions": [
    "Task scope: “Review the Store B monthly sales dashboard for April through June, then choose the June route in the monthly sales operations form.”",
    "Evidence source: “Use the Store B sales dashboard as the evidence source for the June sales route.”",
    "Option conditions: The three available routes are “Route June to low-sales response,” “Keep June on normal sales monitoring,” and “Route June to strong-sales response.”",
    "Required context: The form requires Store unit = Store B, Review month = June, Sales record = Monthly sales, and Operations program = Monthly sales status routing."
  ],
  "uncertain": [
    "The dashboard does not print explicit numeric values above the bars; bar heights are read from the Sales axis gridlines (April ≈ 300, May ≈ 385, June ≈ 200).",
    "No policy table or explicit threshold definition is provided on the page to formally define “low-sales,” “normal,” or “strong-sales” routes.",
    "The exact meaning of the “Average” line (e.g., whether it is the three-month average or a target) is not stated beyond the label “Average.”"
  ]
}
